/** @vitest-environment jsdom */

// Keyframes are built on the server by internal/terminal/keyframe, which models xterm.js. This test checks the model
// against xterm.js itself: for every checkpoint of every scenario, writing the serialized state into a fresh terminal
// must leave the buffer a replay from the start leaves, and continuing both with the remaining steps must keep them
// equal (which checks the hidden state: saved cursors, scroll regions, modes, character sets and the current pen).
// The fixture is generated by `go test ./internal/terminal/keyframe -update-fidelity`.

import { describe, expect, it } from "vitest";
import { Terminal, type IBuffer } from "@xterm/xterm";
import { activateUnicode11 } from "../../features/terminal/xtermAddons";
import fixture from "../fixtures/keyframeFidelity.json";

interface Step {
  out?: string;
  resize?: [number, number];
}

interface Scenario {
  name: string;
  cols: number;
  rows: number;
  steps: Step[];
  checkpoints: { after: number; cols: number; rows: number; state: string }[];
}

// altLineLimit reads xterm's internal alternate buffer line limit; it equals the rows unless the buffer was resized
// while empty.
function altLineLimit(term: Terminal): number {
  const core = (term as unknown as { _core?: { _bufferService?: { buffers?: { alt?: { lines?: { maxLength?: number } } } } } })._core;
  return core?._bufferService?.buffers?.alt?.lines?.maxLength ?? term.rows;
}

function terminal(cols: number, rows: number): Terminal {
  const term = new Terminal({ cols, rows, scrollback: 5000, allowProposedApi: true });
  activateUnicode11(term);
  return term;
}

function write(term: Terminal, data: string): Promise<void> {
  return new Promise((resolve) => term.write(data, resolve));
}

async function apply(term: Terminal, steps: Step[]): Promise<void> {
  for (const step of steps) {
    if (step.resize) term.resize(step.resize[0], step.resize[1]);
    else await write(term, step.out ?? "");
  }
}

function bufferSnapshot(buffer: IBuffer, cols: number) {
  const lines = [];
  for (let y = 0; y < buffer.length; y++) {
    const line = buffer.getLine(y)!;
    const cells = [];
    for (let x = 0; x < cols; x++) {
      const cell = line.getCell(x)!;
      // A wide character cut by a narrower size keeps its first half in the last column, which renders clipped and
      // which no print can rebuild (it wraps or is dropped); it is compared as a blank.
      const cut = x === cols - 1 && cell.getWidth() === 2;
      // A null cell and a space render the same; the model writes spaces for null cells carrying a rendition.
      cells.push([
        cut ? " " : cell.getChars() || " ",
        cut ? 1 : cell.getWidth(),
        cell.getFgColorMode(),
        cell.getFgColor(),
        cell.getBgColorMode(),
        cell.getBgColor(),
        [
          cell.isBold(), cell.isDim(), cell.isItalic(), cell.isUnderline(), cell.isBlink(),
          cell.isInverse(), cell.isInvisible(), cell.isStrikethrough(), cell.isOverline(),
        ].map((on) => (on ? 1 : 0)).join(""),
      ].join("|"));
    }
    lines.push({ y, wrapped: line.isWrapped, cells: cells.join(" ") });
  }
  return { length: buffer.length, baseY: buffer.baseY, cursor: [buffer.cursorX, buffer.cursorY], lines };
}

// xterm keeps an alternate buffer's line limit when it is resized while empty, so it can hold lines above the
// viewport that are never shown and a fresh terminal has no room for; only its viewport is compared.
function viewport(buffer: IBuffer, cols: number, rows: number) {
  const whole = bufferSnapshot(buffer, cols);
  const lines = whole.lines.slice(buffer.baseY, buffer.baseY + rows).map((line) => ({ ...line, y: line.y - buffer.baseY }));
  return { cursor: whole.cursor, lines };
}

function snapshot(term: Terminal) {
  const active = term.buffer.active.type;
  return {
    size: [term.cols, term.rows],
    active,
    modes: [term.modes.insertMode, term.modes.originMode, term.modes.wraparoundMode, term.modes.reverseWraparoundMode],
    normal: bufferSnapshot(term.buffer.normal, term.cols),
    ...(active === "alternate" ? { alternate: viewport(term.buffer.alternate, term.cols, term.rows) } : {}),
  };
}

describe("server keyframes restore what xterm.js replays", () => {
  for (const scenario of fixture as Scenario[]) {
    for (const checkpoint of scenario.checkpoints) {
      it(`${scenario.name} after step ${checkpoint.after}`, async () => {
        const replayed = terminal(scenario.cols, scenario.rows);
        // xterm keeps state in a shown alternate buffer across resizes (its line limit, cells cut by a narrower size)
        // that no restore can rebuild; full-screen programs repaint on resize, so such states are not compared.
        let altResized = false;
        for (const step of scenario.steps.slice(0, checkpoint.after)) {
          if (step.resize && replayed.buffer.active.type === "alternate") altResized = true;
          await apply(replayed, [step]);
          if (replayed.buffer.active.type === "normal") altResized = false;
        }
        if (altResized) return;
        const restored = terminal(checkpoint.cols, checkpoint.rows);
        await write(restored, checkpoint.state);
        expect(snapshot(restored)).toEqual(snapshot(replayed));

        // The same holds for an alternate buffer resized while empty: xterm keeps its old line limit, so a later
        // switch to it scrolls differently from a fresh terminal's. The comparison stops at that switch.
        const staleAlt = altLineLimit(replayed) !== replayed.rows;
        if (staleAlt && replayed.buffer.active.type === "alternate") return;
        for (const step of scenario.steps.slice(checkpoint.after)) {
          if (step.resize && replayed.buffer.active.type === "alternate") break;
          if (staleAlt && step.out?.match(/\x1b\[\?(47|1047|1049)h/)) break;
          await apply(replayed, [step]);
          await apply(restored, [step]);
          expect(snapshot(restored)).toEqual(snapshot(replayed));
        }
        replayed.dispose();
        restored.dispose();
      });
    }
  }
});
